#!/usr/bin/env bash
set -Eeuo pipefail

[[ ${EUID:-$(id -u)} -eq 0 ]] || { echo "[ERROR] Run with sudo/root"; exit 1; }

ROOT="${1:-/root/hyper-hosting-panel}"
SID="${2:-25}"
SRC_CTL="$ROOT/cs16-panel/bin/hyper-cs16-ctl"
SRC_UI="$ROOT/cs16-panel/public/index.php"
LIVE_CTL="/usr/local/sbin/hyper-cs16-ctl"

DOMAIN="$(python3 - <<'PY'
import json
try:
    d=json.load(open('/etc/hyper-cs16/runtime.json',encoding='utf-8'))
    print(d.get('domain') or 'www.avito.hyper-host.pw')
except Exception:
    print('www.avito.hyper-host.pw')
PY
)"
LIVE_UI="/var/www/hyper-host-sites/${DOMAIN}/public_html/index.php"

STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP="/root/hyper-cs16-yapb-toggle-fix-${STAMP}"
mkdir -p "$BACKUP"

for f in "$SRC_CTL" "$SRC_UI" "$LIVE_CTL" "$LIVE_UI"; do
    [[ -f "$f" ]] || continue
    cp -a "$f" "$BACKUP/$(echo "$f" | sed 's#[/ ]#_#g')"
done

echo "========================================================"
echo " HYPER-HOST YaPB TOGGLE FIX v1"
echo " Server: #$SID"
echo " Backup: $BACKUP"
echo "========================================================"

PATCHER="$(mktemp)"
trap 'rm -f "$PATCHER"' EXIT
base64 -d >"$PATCHER" <<'PATCHER_B64'

PATCHER_B64

echo "[1/6] Patching backend + panel..."
python3 "$PATCHER" "$SRC_CTL" "$LIVE_CTL" "$SRC_UI" "$LIVE_UI"

echo "[2/6] Syntax checks..."
python3 -m py_compile "$SRC_CTL"
python3 -m py_compile "$LIVE_CTL"
php -l "$SRC_UI" >/dev/null
php -l "$LIVE_UI" >/dev/null

echo "[3/6] Reinstalling live controller..."
install -m 0755 "$SRC_CTL" "$LIVE_CTL"
python3 -m py_compile "$LIVE_CTL"
chown www-data:www-data "$LIVE_UI" 2>/dev/null || true
chmod 0644 "$LIVE_UI"

echo "[4/6] Checking new command..."
"$LIVE_CTL" --help 2>&1 | grep -q 'bots-enable' || {
    echo "[ERROR] bots-enable command not registered"
    exit 3
}

echo "[5/6] Current YaPB state..."
STATUS="$("$LIVE_CTL" mods-status "$SID")"
echo "$STATUS"

read -r QUOTA DIFF INSTALLED ENABLED < <(python3 - "$STATUS" <<'PY'
import json,sys
d=json.loads(sys.argv[1])
print(
    int(d.get('bots_quota',9)),
    int(d.get('bots_difficulty',3)),
    1 if d.get('bots_installed') else 0,
    1 if d.get('bots_enabled') else 0
)
PY
)

echo "[6/6] Restoring YaPB if it is installed but currently disabled..."
if [[ "$INSTALLED" -eq 1 && "$ENABLED" -eq 0 ]]; then
    echo "Enabling YaPB: quota=$QUOTA difficulty=$DIFF"
    "$LIVE_CTL" bots-enable "$SID" --quota "$QUOTA" --difficulty "$DIFF"
elif [[ "$ENABLED" -eq 1 ]]; then
    echo "[OK] YaPB is already enabled."
else
    echo "[INFO] YaPB is not installed. Use 'Установить YaPB' in the panel."
fi

echo
echo "--- FINAL MODS STATUS ---"
"$LIVE_CTL" mods-status "$SID" || true

echo
echo "--- METAMOD YaPB LINE ---"
grep -ni 'addons/yapb/bin/yapb.so' "/srv/hyper-cs16/servers/${SID}/cstrike/addons/metamod/plugins.ini" || true

echo
echo "--- META LIST ---"
"$LIVE_CTL" rcon "$SID" "meta list" || true

echo
echo "========================================================"
echo "[SUCCESS] YaPB toggle fixed"
echo
echo "Panel behavior now:"
echo "  installed + enabled  -> 'Отключить YaPB'"
echo "  installed + disabled -> 'Включить YaPB'"
echo "  not installed        -> 'Установить YaPB'"
echo
echo "'Сохранить настройки' changes quota/difficulty only;"
echo "it no longer pretends a commented Metamod module is enabled."
echo "========================================================"
